// Builds a small but structurally valid PDF in-process.
// No network and no credentials, and byte-identical on every run - so the SHA-512 that SDP registers is the
// SAME on a second run. That is the point of the demo: the digest identifies the file, nothing else.
// Change a line below and re-run: the digest changes, because the file changed.
function buildPdf(lines) {
  const objects = [];
  objects[1] = '<< /Type /Catalog /Pages 2 0 R >>';
  objects[2] = '<< /Type /Pages /Kids [3 0 R] /Count 1 >>';
  objects[3] =
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents 4 0 R ' +
    '/Resources << /Font << /F1 5 0 R >> >> >>';

  let text = 'BT /F1 14 Tf 60 760 Td 18 TL\n';
  for (const line of lines) {
    text += '(' + line.replace(/([()\\])/g, '\\$1') + ') Tj T*\n';
  }
  text += 'ET';
  objects[4] = '<< /Length ' + Buffer.byteLength(text, 'latin1') + ' >>\nstream\n' + text + '\nendstream';
  objects[5] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';

  let pdf = '%PDF-1.4\n';
  const offsets = [];
  for (let i = 1; i < objects.length; i++) {
    offsets[i] = Buffer.byteLength(pdf, 'latin1');
    pdf += i + ' 0 obj\n' + objects[i] + '\nendobj\n';
  }
  const xrefAt = Buffer.byteLength(pdf, 'latin1');
  pdf += 'xref\n0 ' + objects.length + '\n0000000000 65535 f \n';
  for (let i = 1; i < objects.length; i++) {
    pdf += String(offsets[i]).padStart(10, '0') + ' 00000 n \n';
  }
  pdf += 'trailer\n<< /Size ' + objects.length + ' /Root 1 0 R >>\nstartxref\n' + xrefAt + '\n%%EOF\n';
  return Buffer.from(pdf, 'latin1');
}

const pdf = buildPdf(['SDP demo invoice', 'Amount: 1 240.00 EUR', 'Reference: DEMO-0001']);

return [
  {
    json: { fileName: 'sdp-demo-invoice.pdf', bytes: pdf.length },
    binary: { data: await this.helpers.prepareBinaryData(pdf, 'sdp-demo-invoice.pdf', 'application/pdf') },
  },
];
